INSERT INTO `broadcast_text` (`ID`,`LanguageID`,`MaleText`,`FemaleText`,`EmoteID1`,`EmoteID2`,`EmoteID3`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`SoundEntriesId`,`EmotesID`,`Flags`,`VerifiedBuild`) VALUES 
(1129,7,'','Here we have the Cathedral of Light, the center of spiritual enlightenment here in Stormwind.',0,0,0,0,0,0,0,0,1,18019);
(1130,7,'Why do we have to learn this stuff anyway?','Why do we have to learn this stuff anyway?',0,0,0,0,0,0,0,0,1,18019),
(1140,7,'','Here we have Stormwind Keep. Built upon the ruins of Stormwind Castle, which was destroyed by the Horde in the first Great War.',0,0,0,0,0,0,0,0,1,18019),
(1153,7,'Is it true that the paladins train here?','Is it true that the paladins train here?',0,0,0,0,0,0,0,0,1,18019),
(1154,7,'','Yes, that is true. Paladins and priests alike train their skills and research great truths behind the walls of the Cathedral.',0,0,0,0,0,0,0,0,1,18019),
(1155,7,'','Children if you would please follow me, we will now be going to see the keep where King Varian Wrynn himself sits on his throne.',0,0,0,0,0,0,0,0,1,18019),
(1161,7,'','When the Horde was shattered, men returned here and began to rebuild the once great city as a testament to our own survival.',0,0,0,0,0,0,0,0,1,18019),
(1162,7,'','Yes, well...let\'s head on to the monument dedicated to the heroes of the two Great Wars, the Valley of Heroes. Follow me.',0,0,0,0,0,0,0,0,1,18019),
(1163,7,'','Isn\'t it amazing, children? All who enter the city must walk beneath the watchful eyes of the greatest heroes of our lands.',0,0,0,0,0,0,0,0,1,18019),
(1165,7,'','Breathtaking. Children, when we return to the school, you will each give an oral report on one of these legendary people.',0,0,0,0,0,0,0,0,1,18019),
(1166,7,'','Now, take another long look before we make our way to the Holy District and the great Cathedral of Light.',0,0,0,0,0,0,0,0,1,18019);
